    """Count steps in workflow file"""
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    lines = content.split('\n')
    step_count = 0

    for line in lines:
        # Check if this is a step line
        step_match = re.match(r'^- (\d+)\.', line)
        if step_match:
            step_count += 1

    return step_count

